public class MockChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;
    private readonly Lock _lock = new();

    public MockChatService()
    {
        _channels =
        [
            new Channel(1, "general", "General discussion for the team", 3),
            new Channel(2, "random", "Off-topic fun and memes", 1),
            new Channel(3, "engineering", "Technical discussions and code reviews", 5),
            new Channel(4, "design", "UI/UX design discussions", 0),
            new Channel(5, "announcements", "Important team announcements", 2)
        ];

        var now = DateTime.UtcNow;
        _messages =
        [
            // General channel
            new Message(1, 1, "Alice", "Good morning everyone! 👋 Ready for the sprint planning?", now.AddHours(-5), null, [new Reaction("👍", ["Bob", "Carol"]), new Reaction("👋", ["Dave"])]),
            new Message(2, 1, "Bob", "Morning! Yes, I've prepared the backlog items.", now.AddHours(-4.9), null, []),
            new Message(3, 1, "Carol", "Can we also discuss the deployment pipeline today?", now.AddHours(-4.8), null, [new Reaction("👍", ["Alice"])]),
            new Message(4, 1, "Alice", "Sure, let's add it to the agenda.", now.AddHours(-4.7), 3, []),
            new Message(5, 1, "Dave", "I'll prepare the metrics dashboard before the meeting.", now.AddHours(-4), null, [new Reaction("🎉", ["Alice", "Bob"])]),
            new Message(6, 1, "Bob", "Has anyone reviewed the PR for the auth module?", now.AddMinutes(-45), null, []),
            new Message(7, 1, "Carol", "I left some comments on it. Looks good overall!", now.AddMinutes(-30), 6, []),
            new Message(8, 1, "Alice", "I'll take a second look after lunch.", now.AddMinutes(-15), 6, [new Reaction("👀", ["Bob"])]),

            // Random channel
            new Message(9, 2, "Dave", "Anyone up for lunch at the new Thai place?", now.AddHours(-2), null, [new Reaction("🔥", ["Carol"]), new Reaction("👍", ["Alice"])]),
            new Message(10, 2, "Carol", "Count me in! 🍜", now.AddHours(-1.9), 9, []),
            new Message(11, 2, "Bob", "Check out this hilarious meme about code reviews 😂", now.AddMinutes(-50), null, [new Reaction("😂", ["Alice", "Dave", "Carol"])]),
            new Message(12, 2, "Alice", "Friday game night this week? We could do board games.", now.AddMinutes(-20), null, [new Reaction("🎉", ["Bob", "Dave"])]),

            // Engineering channel
            new Message(13, 3, "Carol", "I've pushed the new CI/CD pipeline config. Please review.", now.AddHours(-6), null, [new Reaction("👀", ["Bob", "Alice"])]),
            new Message(14, 3, "Bob", "The build times improved by 40% after the caching changes!", now.AddHours(-3), null, [new Reaction("🎉", ["Alice", "Carol", "Dave"]), new Reaction("🔥", ["Carol"])]),
            new Message(15, 3, "Alice", "Nice work Bob! What caching strategy did you use?", now.AddHours(-2.8), 14, []),
            new Message(16, 3, "Bob", "Docker layer caching + npm cache restore. Happy to do a knowledge share.", now.AddHours(-2.5), 14, [new Reaction("👍", ["Alice", "Dave"])]),
            new Message(17, 3, "Dave", "We need to upgrade the database driver. Current version has a known vulnerability.", now.AddMinutes(-90), null, [new Reaction("👍", ["Carol"])]),
            new Message(18, 3, "Carol", "I can handle the upgrade. Will create a ticket.", now.AddMinutes(-60), 17, []),

            // Design channel
            new Message(19, 4, "Dave", "Here are the new mockups for the dashboard redesign.", now.AddHours(-8), null, [new Reaction("❤️", ["Alice", "Bob"])]),
            new Message(20, 4, "Alice", "Love the color palette! The contrast ratios look great.", now.AddHours(-7), 19, []),

            // Announcements channel
            new Message(21, 5, "Alice", "🚀 v2.5.0 is now live in production! Great work team!", now.AddDays(-1), null, [new Reaction("🎉", ["Bob", "Carol", "Dave"]), new Reaction("🔥", ["Bob"])]),
            new Message(22, 5, "Bob", "Reminder: All-hands meeting tomorrow at 10am.", now.AddHours(-3), null, [new Reaction("👍", ["Alice", "Carol"])]),
        ];

        _nextMessageId = 23;
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_channels.Select(c => c).ToList());
        }
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        lock (_lock)
        {
            var result = _messages
                .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
                .OrderBy(m => m.SentAt)
                .ToList();

            // For "load older", skip is from the beginning (oldest)
            var page = result
                .Skip(Math.Max(0, result.Count - skip - take))
                .Take(Math.Min(take, Math.Max(0, result.Count - skip)))
                .ToList();

            return Task.FromResult(page);
        }
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        lock (_lock)
        {
            var msg = new Message(_nextMessageId++, channelId, "You", content, DateTime.UtcNow, replyToId, []);
            _messages.Add(msg);
            return Task.FromResult(msg);
        }
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        lock (_lock)
        {
            var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
            if (root == null) return Task.FromResult(new List<Message>());

            var replies = _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList();

            var result = new List<Message> { root };
            result.AddRange(replies);
            return Task.FromResult(result);
        }
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        lock (_lock)
        {
            var idx = _messages.FindIndex(m => m.Id == messageId);
            if (idx < 0) return Task.CompletedTask;

            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == emoji);

            if (existing >= 0)
            {
                var reaction = reactions[existing];
                var users = reaction.Users.ToList();
                if (users.Contains("You"))
                    users.Remove("You");
                else
                    users.Add("You");

                if (users.Count == 0)
                    reactions.RemoveAt(existing);
                else
                    reactions[existing] = reaction with { Users = users };
            }
            else
            {
                reactions.Add(new Reaction(emoji, ["You"]));
            }

            _messages[idx] = msg with { Reactions = reactions };
            return Task.CompletedTask;
        }
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        lock (_lock)
        {
            var idx = _channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                _channels[idx] = _channels[idx] with { UnreadCount = 0 };
            }
            return Task.CompletedTask;
        }
    }
}

