@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="chat-container">
    @* ===== LEFT SIDEBAR ===== *@
    <div class="sidebar">
        <div class="sidebar-header">
            <h4>💬 TeamChat</h4>
        </div>
        <div class="channel-list">
            @if (channels is not null)
            {
                @foreach (var channel in channels)
                {
                    <div class="channel-item @(activeChannel?.Id == channel.Id ? "active" : "")"
                         @onclick="() => SelectChannel(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@channel.Description</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </div>
                }
            }
        </div>
    </div>

    @* ===== MAIN MESSAGE AREA ===== *@
    <div class="main-area">
        @if (activeChannel is not null)
        {
            <div class="main-header">
                <h5># @activeChannel.Name</h5>
                <span class="header-desc">@activeChannel.Description</span>
            </div>

            <div class="message-list" id="message-list" @ref="messageListRef">
                @if (loadingMore)
                {
                    <div class="loading-indicator">
                        <div class="spinner-border spinner-border-sm text-secondary" role="status"></div>
                        <span>Loading older messages...</span>
                    </div>
                }
                @if (messages is not null)
                {
                    @foreach (var msg in messages)
                    {
                        <div class="message-card" @key="msg.Id">
                            <div class="message-hover-actions">
                                <button class="btn btn-sm btn-outline-secondary" title="Reply"
                                        @onclick="() => OpenThread(msg.Id)">💬</button>
                                <button class="btn btn-sm btn-outline-secondary" title="React"
                                        @onclick="() => ShowEmojiPicker(msg.Id)">😊</button>
                            </div>
                            <div class="avatar" style="background-color: @GetAvatarColor(msg.Author)">
                                @msg.Author[0]
                            </div>
                            <div class="message-body">
                                <div class="message-meta">
                                    <span class="author-name">@msg.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>
                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reactions-row">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
                                                    @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }
                                @if (threadSummaries.TryGetValue(msg.Id, out var summary))
                                {
                                    <button class="thread-link" @onclick="() => OpenThread(msg.Id)">
                                        💬 @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                        <span class="thread-time">Last reply @FormatRelativeTime(summary.LastReplyAt)</span>
                                    </button>
                                }
                            </div>
                            @if (emojiPickerMessageId == msg.Id)
                            {
                                <div class="emoji-picker">
                                    @foreach (var emoji in commonEmojis)
                                    {
                                        <button class="emoji-btn" @onclick="() => PickEmoji(msg.Id, emoji)">@emoji</button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="form-control" rows="2" placeholder="Message #@activeChannel.Name"
                          @bind="newMessage" @bind:event="oninput"
                          @onkeydown="HandleMainKeyDown"></textarea>
                <button class="btn btn-primary send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessage)">
                    Send
                </button>
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center h-100">
                <div class="spinner-border text-primary" role="status"></div>
            </div>
        }
    </div>

    @* ===== RIGHT THREAD PANEL ===== *@
    @if (openThreadRootId is not null && threadMessages is not null)
    {
        <div class="thread-panel">
            <div class="thread-header">
                <h6>Thread</h6>
                <button class="btn btn-sm btn-outline-secondary" @onclick="CloseThread">✕</button>
            </div>

            <div class="thread-messages">
                @foreach (var msg in threadMessages)
                {
                    var isRoot = msg.Id == openThreadRootId;
                    <div class="@(isRoot ? "thread-root-message" : "message-card")" @key="msg.Id">
                        <div class="avatar avatar-sm" style="background-color: @GetAvatarColor(msg.Author)">
                            @msg.Author[0]
                        </div>
                        <div class="message-body">
                            <div class="message-meta">
                                <span class="author-name">@msg.Author</span>
                                <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>
                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
                                                @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea class="form-control" rows="2" placeholder="Reply in thread..."
                          @bind="newReply" @bind:event="oninput"
                          @onkeydown="HandleReplyKeyDown"></textarea>
                <button class="btn btn-primary send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(newReply)">
                    Reply
                </button>
            </div>
        </div>
    }
</div>

@code {
    private List<Channel>? channels;
    private Channel? activeChannel;
    private List<Message>? messages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private int? openThreadRootId;
    private List<Message>? threadMessages;
    private string newMessage = "";
    private string newReply = "";
    private int skip = 0;
    private int take = 25;
    private bool loadingMore;
    private int? emojiPickerMessageId;
    private bool isLoading = true;

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "👀", "🔥"];
    private static readonly string[] avatarColors = ["#e74c3c", "#3498db", "#2ecc71", "#f39c12", "#9b59b6", "#1abc9c", "#e67e22", "#34495e", "#e91e63", "#00bcd4"];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
        isLoading = false;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Chat.razor.js");
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannel = channel;
        skip = 0;
        openThreadRootId = null;
        threadMessages = null;
        emojiPickerMessageId = null;
        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channel.Id);
        channels = await ChatService.GetChannelsAsync();
        await ScrollToBottom();
    }

    private async Task LoadMessages()
    {
        if (activeChannel is null) return;
        messages = await ChatService.GetMessagesAsync(activeChannel.Id, skip, take);
        BuildThreadSummaries();
    }

    [JSInvokable]
    public async Task LoadOlderMessages()
    {
        if (activeChannel is null || loadingMore) return;
        loadingMore = true;
        StateHasChanged();

        skip += take;
        var older = await ChatService.GetMessagesAsync(activeChannel.Id, skip, take);
        if (older.Count > 0 && messages is not null)
        {
            messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        loadingMore = false;
        StateHasChanged();
    }

    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        if (messages is null) return;

        // Get all replies for current channel from messages (including thread messages)
        var allMessages = messages.ToList();
        if (threadMessages is not null)
            allMessages.AddRange(threadMessages.Where(tm => !allMessages.Any(m => m.Id == tm.Id)));

        // We need to check if any message in the service has ReplyToId pointing to our messages
        // For simplicity, build from what we know
        var replyGroups = allMessages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyGroups)
        {
            var replies = group.OrderBy(m => m.SentAt).ToList();
            threadSummaries[group.Key] = new ThreadSummary(group.Key, replies.Count, replies.Last().SentAt);
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessage) || activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannel.Id, newMessage.Trim(), null);
        messages ??= [];
        messages.Add(msg);
        newMessage = "";
        await ScrollToBottom();
    }

    private async Task OpenThread(int rootMessageId)
    {
        openThreadRootId = rootMessageId;
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        BuildThreadSummaries();
        emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        openThreadRootId = null;
        threadMessages = null;
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(newReply) || openThreadRootId is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, newReply.Trim(), openThreadRootId);
        threadMessages ??= [];
        threadMessages.Add(reply);
        newReply = "";
        BuildThreadSummaries();
    }

    private async Task ToggleReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh affected message lists
        if (activeChannel is not null)
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, skip + take);
        if (openThreadRootId is not null)
            threadMessages = await ChatService.GetThreadAsync(openThreadRootId.Value);
        BuildThreadSummaries();
        emojiPickerMessageId = null;
    }

    private void ShowEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private void PickEmoji(int messageId, string emoji)
    {
        _ = ToggleReaction(messageId, emoji);
    }

    private async Task HandleMainKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && e.CtrlKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleReplyKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && e.CtrlKey)
        {
            await SendReply();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            if (jsModule is not null)
            {
                await Task.Yield();
                await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            }
        }
        catch { /* element may not be rendered yet */ }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalHours < 48) return "Yesterday";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string GetAvatarColor(string author)
    {
        var hash = Math.Abs(author.GetHashCode());
        return avatarColors[hash % avatarColors.Length];
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch { }
        }
    }
}

/* ===== Layout ===== */
.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* ===== Sidebar ===== */
.sidebar {
    width: 260px;
    min-width: 260px;
    background: #1a1a2e;
    color: #e0e0e0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.sidebar-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.2rem;
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    padding: 10px 20px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s ease;
    border-left: 3px solid transparent;
}

.channel-item:hover {
    background: rgba(255,255,255,0.06);
}

.channel-item.active {
    background: rgba(255,255,255,0.1);
    border-left-color: #6c63ff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-desc {
    font-size: 0.75rem;
    color: #8888a0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

.unread-badge {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    background: #6c63ff;
    color: #fff;
    border-radius: 10px;
    padding: 1px 8px;
    font-size: 0.72rem;
    font-weight: 700;
}

/* ===== Main Area ===== */
.main-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.main-header {
    padding: 14px 24px;
    border-bottom: 1px solid #e8e8e8;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.main-header h5 {
    margin: 0;
    font-weight: 700;
    font-size: 1.1rem;
}

.header-desc {
    color: #888;
    font-size: 0.85rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

/* ===== Message Cards ===== */
.message-card {
    display: flex;
    gap: 12px;
    padding: 8px 12px;
    border-radius: 8px;
    position: relative;
    transition: background 0.1s ease;
    margin-bottom: 2px;
}

.message-card:hover {
    background: #f5f5f7;
}

.message-hover-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: none;
    gap: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    z-index: 10;
}

.message-card:hover .message-hover-actions {
    display: flex;
}

.message-hover-actions .btn {
    font-size: 0.75rem;
    padding: 2px 6px;
    border: none;
}

.avatar {
    width: 38px;
    height: 38px;
    min-width: 38px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-weight: 700;
    font-size: 1rem;
    flex-shrink: 0;
}

.avatar-sm {
    width: 30px;
    height: 30px;
    min-width: 30px;
    font-size: 0.8rem;
}

.message-body {
    flex: 1;
    min-width: 0;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author-name {
    font-weight: 700;
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    font-size: 0.92rem;
    line-height: 1.45;
    color: #333;
    word-break: break-word;
}

/* ===== Reactions ===== */
.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 12px;
    border: 1px solid #e0e0e0;
    background: #f5f5f5;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.15s ease;
}

.reaction-pill:hover {
    background: #e8e8ff;
    border-color: #6c63ff;
}

.reaction-pill.reacted {
    background: #e8e8ff;
    border-color: #6c63ff;
    color: #6c63ff;
}

/* ===== Thread Link ===== */
.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 6px;
    background: none;
    border: none;
    color: #6c63ff;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 4px 0;
}

.thread-link:hover {
    text-decoration: underline;
}

.thread-time {
    font-weight: 400;
    color: #999;
}

/* ===== Emoji Picker ===== */
.emoji-picker {
    position: absolute;
    top: -8px;
    right: 80px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 4px 16px rgba(0,0,0,0.12);
    z-index: 20;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 6px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #f0f0f0;
}

/* ===== Message Input ===== */
.message-input-area {
    padding: 12px 24px;
    border-top: 1px solid #e8e8e8;
    display: flex;
    gap: 10px;
    align-items: flex-end;
    flex-shrink: 0;
    background: #fff;
}

.message-input-area .form-control {
    resize: none;
    border-radius: 8px;
    font-size: 0.9rem;
}

.send-btn {
    border-radius: 8px;
    padding: 8px 20px;
    font-weight: 600;
    white-space: nowrap;
}

/* ===== Thread Panel ===== */
.thread-panel {
    width: 360px;
    min-width: 360px;
    border-left: 1px solid #e8e8e8;
    display: flex;
    flex-direction: column;
    background: #fafafa;
    animation: slideIn 0.2s ease;
}

@keyframes slideIn {
    from { transform: translateX(20px); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-header h6 {
    margin: 0;
    font-weight: 700;
    font-size: 1rem;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-root-message {
    display: flex;
    gap: 10px;
    padding: 12px;
    background: #eef0ff;
    border-radius: 8px;
    border-left: 3px solid #6c63ff;
    margin-bottom: 12px;
}

.thread-panel .message-card {
    padding: 6px 8px;
}

.thread-panel .message-input-area {
    padding: 10px 16px;
    background: #fafafa;
}

/* ===== Scrollbar ===== */
.message-list::-webkit-scrollbar,
.channel-list::-webkit-scrollbar,
.thread-messages::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-track,
.channel-list::-webkit-scrollbar-track,
.thread-messages::-webkit-scrollbar-track {
    background: transparent;
}

.message-list::-webkit-scrollbar-thumb,
.thread-messages::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.channel-list::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.15);
    border-radius: 3px;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
    .sidebar {
        width: 200px;
        min-width: 200px;
    }
    .thread-panel {
        width: 280px;
        min-width: 280px;
    }
}

@media (max-width: 600px) {
    .sidebar {
        width: 60px;
        min-width: 60px;
    }
    .channel-desc,
    .sidebar-header h4 {
        display: none;
    }
    .channel-name {
        font-size: 0.75rem;
    }
    .thread-panel {
        position: absolute;
        right: 0;
        top: 0;
        height: 100vh;
        z-index: 100;
        box-shadow: -4px 0 20px rgba(0,0,0,0.15);
    }
}

let scrollListener = null;
let scrollElement = null;

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

export function onScrollToTop(element, dotNetRef) {
    if (!element) return;
    scrollElement = element;

    scrollListener = () => {
        if (element.scrollTop <= 5 && dotNetRef) {
            dotNetRef.invokeMethodAsync('LoadOlderMessages');
        }
    };

    element.addEventListener('scroll', scrollListener);
}

export function dispose() {
    if (scrollElement && scrollListener) {
        scrollElement.removeEventListener('scroll', scrollListener);
    }
    scrollListener = null;
    scrollElement = null;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="chat-container">
    @* ===== LEFT SIDEBAR ===== *@
    <div class="sidebar">
        <div class="sidebar-header">
            <h4>💬 TeamChat</h4>
        </div>
        <div class="channel-list">
            @if (channels is not null)
            {
                @foreach (var channel in channels)
                {
                    <div class="channel-item @(activeChannel?.Id == channel.Id ? "active" : "")"
                         @onclick="() => SelectChannel(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@channel.Description</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </div>
                }
            }
        </div>
    </div>

    @* ===== MAIN MESSAGE AREA ===== *@
    <div class="main-area">
        @if (activeChannel is not null)
        {
            <div class="main-header">
                <h5># @activeChannel.Name</h5>
                <span class="header-desc">@activeChannel.Description</span>
            </div>

            <div class="message-list" id="message-list" @ref="messageListRef">
                @if (loadingMore)
                {
                    <div class="loading-indicator">
                        <div class="spinner-border spinner-border-sm text-secondary" role="status"></div>
                        <span>Loading older messages...</span>
                    </div>
                }
                @if (messages is not null)
                {
                    @foreach (var msg in messages)
                    {
                        <div class="message-card" @key="msg.Id">
                            <div class="message-hover-actions">
                                <button class="btn btn-sm btn-outline-secondary" title="Reply"
                                        @onclick="() => OpenThread(msg.Id)">💬</button>
                                <button class="btn btn-sm btn-outline-secondary" title="React"
                                        @onclick="() => ShowEmojiPicker(msg.Id)">😊</button>
                            </div>
                            <div class="avatar" style="background-color: @GetAvatarColor(msg.Author)">
                                @msg.Author[0]
                            </div>
                            <div class="message-body">
                                <div class="message-meta">
                                    <span class="author-name">@msg.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>
                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reactions-row">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
                                                    @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }
                                @if (threadSummaries.TryGetValue(msg.Id, out var summary))
                                {
                                    <button class="thread-link" @onclick="() => OpenThread(msg.Id)">
                                        💬 @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                        <span class="thread-time">Last reply @FormatRelativeTime(summary.LastReplyAt)</span>
                                    </button>
                                }
                            </div>
                            @if (emojiPickerMessageId == msg.Id)
                            {
                                <div class="emoji-picker">
                                    @foreach (var emoji in commonEmojis)
                                    {
                                        <button class="emoji-btn" @onclick="() => PickEmoji(msg.Id, emoji)">@emoji</button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="form-control" rows="2" placeholder="Message #@activeChannel.Name"
                          @bind="newMessage" @bind:event="oninput"
                          @onkeydown="HandleMainKeyDown"></textarea>
                <button class="btn btn-primary send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessage)">
                    Send
                </button>
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center h-100">
                <div class="spinner-border text-primary" role="status"></div>
            </div>
        }
    </div>

    @* ===== RIGHT THREAD PANEL ===== *@
    @if (openThreadRootId is not null && threadMessages is not null)
    {
        <div class="thread-panel">
            <div class="thread-header">
                <h6>Thread</h6>
                <button class="btn btn-sm btn-outline-secondary" @onclick="CloseThread">✕</button>
            </div>

            <div class="thread-messages">
                @foreach (var msg in threadMessages)
                {
                    var isRoot = msg.Id == openThreadRootId;
                    <div class="@(isRoot ? "thread-root-message" : "message-card")" @key="msg.Id">
                        <div class="avatar avatar-sm" style="background-color: @GetAvatarColor(msg.Author)">
                            @msg.Author[0]
                        </div>
                        <div class="message-body">
                            <div class="message-meta">
                                <span class="author-name">@msg.Author</span>
                                <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>
                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
                                                @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea class="form-control" rows="2" placeholder="Reply in thread..."
                          @bind="newReply" @bind:event="oninput"
                          @onkeydown="HandleReplyKeyDown"></textarea>
                <button class="btn btn-primary send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(newReply)">
                    Reply
                </button>
            </div>
        </div>
    }
</div>

@code {
    private List<Channel>? channels;
    private Channel? activeChannel;
    private List<Message>? messages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private int? openThreadRootId;
    private List<Message>? threadMessages;
    private string newMessage = "";
    private string newReply = "";
    private int skip = 0;
    private int take = 25;
    private bool loadingMore;
    private int? emojiPickerMessageId;
    private bool isLoading = true;

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "👀", "🔥"];
    private static readonly string[] avatarColors = ["#e74c3c", "#3498db", "#2ecc71", "#f39c12", "#9b59b6", "#1abc9c", "#e67e22", "#34495e", "#e91e63", "#00bcd4"];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
        isLoading = false;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Chat.razor.js");
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannel = channel;
        skip = 0;
        openThreadRootId = null;
        threadMessages = null;
        emojiPickerMessageId = null;
        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channel.Id);
        channels = await ChatService.GetChannelsAsync();
        await ScrollToBottom();
    }

    private async Task LoadMessages()
    {
        if (activeChannel is null) return;
        messages = await ChatService.GetMessagesAsync(activeChannel.Id, skip, take);
        BuildThreadSummaries();
    }

    [JSInvokable]
    public async Task LoadOlderMessages()
    {
        if (activeChannel is null || loadingMore) return;
        loadingMore = true;
        StateHasChanged();

        skip += take;
        var older = await ChatService.GetMessagesAsync(activeChannel.Id, skip, take);
        if (older.Count > 0 && messages is not null)
        {
            messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        loadingMore = false;
        StateHasChanged();
    }

    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        if (messages is null) return;

        // Get all replies for current channel from messages (including thread messages)
        var allMessages = messages.ToList();
        if (threadMessages is not null)
            allMessages.AddRange(threadMessages.Where(tm => !allMessages.Any(m => m.Id == tm.Id)));

        // We need to check if any message in the service has ReplyToId pointing to our messages
        // For simplicity, build from what we know
        var replyGroups = allMessages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyGroups)
        {
            var replies = group.OrderBy(m => m.SentAt).ToList();
            threadSummaries[group.Key] = new ThreadSummary(group.Key, replies.Count, replies.Last().SentAt);
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessage) || activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannel.Id, newMessage.Trim(), null);
        messages ??= [];
        messages.Add(msg);
        newMessage = "";
        await ScrollToBottom();
    }

    private async Task OpenThread(int rootMessageId)
    {
        openThreadRootId = rootMessageId;
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        BuildThreadSummaries();
        emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        openThreadRootId = null;
        threadMessages = null;
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(newReply) || openThreadRootId is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, newReply.Trim(), openThreadRootId);
        threadMessages ??= [];
        threadMessages.Add(reply);
        newReply = "";
        BuildThreadSummaries();
    }

    private async Task ToggleReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh affected message lists
        if (activeChannel is not null)
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, skip + take);
        if (openThreadRootId is not null)
            threadMessages = await ChatService.GetThreadAsync(openThreadRootId.Value);
        BuildThreadSummaries();
        emojiPickerMessageId = null;
    }

    private void ShowEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private void PickEmoji(int messageId, string emoji)
    {
        _ = ToggleReaction(messageId, emoji);
    }

    private async Task HandleMainKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && e.CtrlKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleReplyKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && e.CtrlKey)
        {
            await SendReply();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            if (jsModule is not null)
            {
                await Task.Yield();
                await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            }
        }
        catch { /* element may not be rendered yet */ }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalHours < 48) return "Yesterday";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string GetAvatarColor(string author)
    {
        var hash = Math.Abs(author.GetHashCode());
        return avatarColors[hash % avatarColors.Length];
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch { }
        }
    }
}

