+/* ===== Layout ===== */
+.chat-container {
+    display: flex;
+    height: 100vh;
+    overflow: hidden;
+    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
+}
+
+/* ===== Sidebar ===== */
+.sidebar {
+    width: 260px;
+    min-width: 260px;
+    background: #1a1a2e;
+    color: #e0e0e0;
+    display: flex;
+    flex-direction: column;
+    overflow: hidden;
+}
+
+.sidebar-header {
+    padding: 16px 20px;
+    border-bottom: 1px solid rgba(255,255,255,0.08);
+}
+
+.sidebar-header h4 {
+    margin: 0;
+    color: #fff;
+    font-size: 1.2rem;
+    font-weight: 700;
+}
+
+.channel-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 0;
+}
+
+.channel-item {
+    padding: 10px 20px;
+    cursor: pointer;
+    position: relative;
+    transition: background 0.15s ease;
+    border-left: 3px solid transparent;
+}
+
+.channel-item:hover {
+    background: rgba(255,255,255,0.06);
+}
+
+.channel-item.active {
+    background: rgba(255,255,255,0.1);
+    border-left-color: #6c63ff;
+}
+
+.channel-name {
+    font-weight: 600;
+    font-size: 0.95rem;
+    color: #fff;
+}
+
+.channel-desc {
+    font-size: 0.75rem;
+    color: #8888a0;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+    margin-top: 2px;
+}
+
+.unread-badge {
+    position: absolute;
+    right: 16px;
+    top: 50%;
+    transform: translateY(-50%);
+    background: #6c63ff;
+    color: #fff;
+    border-radius: 10px;
+    padding: 1px 8px;
+    font-size: 0.72rem;
+    font-weight: 700;
+}
+
+/* ===== Main Area ===== */
+.main-area {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    min-width: 0;
+    background: #fff;
+}
+
+.main-header {
+    padding: 14px 24px;
+    border-bottom: 1px solid #e8e8e8;
+    display: flex;
+    align-items: baseline;
+    gap: 12px;
+    flex-shrink: 0;
+}
+
+.main-header h5 {
+    margin: 0;
+    font-weight: 700;
+    font-size: 1.1rem;
+}
+
+.header-desc {
+    color: #888;
+    font-size: 0.85rem;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 24px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    color: #888;
+    font-size: 0.85rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    gap: 8px;
+}
+
+/* ===== Message Cards ===== */
+.message-card {
+    display: flex;
+    gap: 12px;
+    padding: 8px 12px;
+    border-radius: 8px;
+    position: relative;
+    transition: background 0.1s ease;
+    margin-bottom: 2px;
+}
+
+.message-card:hover {
+    background: #f5f5f7;
+}
+
+.message-hover-actions {
+    position: absolute;
+    top: -12px;
+    right: 12px;
+    display: none;
+    gap: 4px;
+    background: #fff;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+    padding: 2px 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
+    z-index: 10;
+}
+
+.message-card:hover .message-hover-actions {
+    display: flex;
+}
+
+.message-hover-actions .btn {
+    font-size: 0.75rem;
+    padding: 2px 6px;
+    border: none;
+}
+
+.avatar {
+    width: 38px;
+    height: 38px;
+    min-width: 38px;
+    border-radius: 8px;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    color: #fff;
+    font-weight: 700;
+    font-size: 1rem;
+    flex-shrink: 0;
+}
+
+.avatar-sm {
+    width: 30px;
+    height: 30px;
+    min-width: 30px;
+    font-size: 0.8rem;
+}
+
+.message-body {
+    flex: 1;
+    min-width: 0;
+}
+
+.message-meta {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 2px;
+}
+
+.author-name {
+    font-weight: 700;
+    font-size: 0.9rem;
+}
+
+.timestamp {
+    font-size: 0.75rem;
+    color: #999;
+}
+
+.message-content {
+    font-size: 0.92rem;
+    line-height: 1.45;
+    color: #333;
+    word-break: break-word;
+}
+
+/* ===== Reactions ===== */
+.reactions-row {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 4px;
+    margin-top: 6px;
+}
+
+.reaction-pill {
+    display: inline-flex;
+    align-items: center;
+    gap: 4px;
+    padding: 2px 8px;
+    border-radius: 12px;
+    border: 1px solid #e0e0e0;
+    background: #f5f5f5;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: all 0.15s ease;
+}
+
+.reaction-pill:hover {
+    background: #e8e8ff;
+    border-color: #6c63ff;
+}
+
+.reaction-pill.reacted {
+    background: #e8e8ff;
+    border-color: #6c63ff;
+    color: #6c63ff;
+}
+
+/* ===== Thread Link ===== */
+.thread-link {
+    display: inline-flex;
+    align-items: center;
+    gap: 6px;
+    margin-top: 6px;
+    background: none;
+    border: none;
+    color: #6c63ff;
+    font-size: 0.82rem;
+    font-weight: 600;
+    cursor: pointer;
+    padding: 4px 0;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.thread-time {
+    font-weight: 400;
+    color: #999;
+}
+
+/* ===== Emoji Picker ===== */
+.emoji-picker {
+    position: absolute;
+    top: -8px;
+    right: 80px;
+    background: #fff;
+    border: 1px solid #ddd;
+    border-radius: 8px;
+    padding: 6px;
+    display: flex;
+    gap: 2px;
+    box-shadow: 0 4px 16px rgba(0,0,0,0.12);
+    z-index: 20;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.3rem;
+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 6px;
+    transition: background 0.1s;
+}
+
+.emoji-btn:hover {
+    background: #f0f0f0;
+}
+
+/* ===== Message Input ===== */
+.message-input-area {
+    padding: 12px 24px;
+    border-top: 1px solid #e8e8e8;
+    display: flex;
+    gap: 10px;
+    align-items: flex-end;
+    flex-shrink: 0;
+    background: #fff;
+}
+
+.message-input-area .form-control {
+    resize: none;
+    border-radius: 8px;
+    font-size: 0.9rem;
+}
+
+.send-btn {
+    border-radius: 8px;
+    padding: 8px 20px;
+    font-weight: 600;
+    white-space: nowrap;
+}
+
+/* ===== Thread Panel ===== */
+.thread-panel {
+    width: 360px;
+    min-width: 360px;
+    border-left: 1px solid #e8e8e8;
+    display: flex;
+    flex-direction: column;
+    background: #fafafa;
+    animation: slideIn 0.2s ease;
+}
+
+@keyframes slideIn {
+    from { transform: translateX(20px); opacity: 0; }
+    to { transform: translateX(0); opacity: 1; }
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 14px 20px;
+    border-bottom: 1px solid #e8e8e8;
+    flex-shrink: 0;
+}
+
+.thread-header h6 {
+    margin: 0;
+    font-weight: 700;
+    font-size: 1rem;
+}
+
+.thread-messages {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-root-message {
+    display: flex;
+    gap: 10px;
+    padding: 12px;
+    background: #eef0ff;
+    border-radius: 8px;
+    border-left: 3px solid #6c63ff;
+    margin-bottom: 12px;
+}
+
+.thread-panel .message-card {
+    padding: 6px 8px;
+}
+
+.thread-panel .message-input-area {
+    padding: 10px 16px;
+    background: #fafafa;
+}
+
+/* ===== Scrollbar ===== */
+.message-list::-webkit-scrollbar,
+.channel-list::-webkit-scrollbar,
+.thread-messages::-webkit-scrollbar {
+    width: 6px;
+}
+
+.message-list::-webkit-scrollbar-track,
+.channel-list::-webkit-scrollbar-track,
+.thread-messages::-webkit-scrollbar-track {
+    background: transparent;
+}
+
+.message-list::-webkit-scrollbar-thumb,
+.thread-messages::-webkit-scrollbar-thumb {
+    background: #ccc;
+    border-radius: 3px;
+}
+
+.channel-list::-webkit-scrollbar-thumb {
+    background: rgba(255,255,255,0.15);
+    border-radius: 3px;
+}
+
+/* ===== Responsive ===== */
+@media (max-width: 900px) {
+    .sidebar {
+        width: 200px;
+        min-width: 200px;
+    }
+    .thread-panel {
+        width: 280px;
+        min-width: 280px;
+    }
+}
+
+@media (max-width: 600px) {
+    .sidebar {
+        width: 60px;
+        min-width: 60px;
+    }
+    .channel-desc,
+    .sidebar-header h4 {
+        display: none;
+    }
+    .channel-name {
+        font-size: 0.75rem;
+    }
+    .thread-panel {
+        position: absolute;
+        right: 0;
+        top: 0;
+        height: 100vh;
+        z-index: 100;
+        box-shadow: -4px 0 20px rgba(0,0,0,0.15);
+    }
+}
+

