1. @page "/chat"
2. @layout ChatLayout
3. @rendermode InteractiveServer
4. @inject IChatService ChatService
5. @inject IJSRuntime JS
6. @implements IAsyncDisposable
7. 
8. <div class="chat-container">
9.     @* ===== LEFT SIDEBAR ===== *@
10.     <div class="sidebar">
11.         <div class="sidebar-header">
12.             <h4>💬 TeamChat</h4>
13.         </div>
14.         <div class="channel-list">
15.             @if (channels is not null)
16.             {
17.                 @foreach (var channel in channels)
18.                 {
19.                     <div class="channel-item @(activeChannel?.Id == channel.Id ? "active" : "")"
20.                          @onclick="() => SelectChannel(channel)">
21.                         <div class="channel-name"># @channel.Name</div>
22.                         <div class="channel-desc">@channel.Description</div>
23.                         @if (channel.UnreadCount > 0)
24.                         {
25.                             <span class="unread-badge">@channel.UnreadCount</span>
26.                         }
27.                     </div>
28.                 }
29.             }
30.         </div>
31.     </div>
32. 
33.     @* ===== MAIN MESSAGE AREA ===== *@
34.     <div class="main-area">
35.         @if (activeChannel is not null)
36.         {
37.             <div class="main-header">
38.                 <h5># @activeChannel.Name</h5>
39.                 <span class="header-desc">@activeChannel.Description</span>
40.             </div>
41. 
42.             <div class="message-list" id="message-list" @ref="messageListRef">
43.                 @if (loadingMore)
44.                 {
45.                     <div class="loading-indicator">
46.                         <div class="spinner-border spinner-border-sm text-secondary" role="status"></div>
47.                         <span>Loading older messages...</span>
48.                     </div>
49.                 }
50.                 @if (messages is not null)
51.                 {
52.                     @foreach (var msg in messages)
53.                     {
54.                         <div class="message-card" @key="msg.Id">
55.                             <div class="message-hover-actions">
56.                                 <button class="btn btn-sm btn-outline-secondary" title="Reply"
57.                                         @onclick="() => OpenThread(msg.Id)">💬</button>
58.                                 <button class="btn btn-sm btn-outline-secondary" title="React"
59.                                         @onclick="() => ShowEmojiPicker(msg.Id)">😊</button>
60.                             </div>
61.                             <div class="avatar" style="background-color: @GetAvatarColor(msg.Author)">
62.                                 @msg.Author[0]
63.                             </div>
64.                             <div class="message-body">
65.                                 <div class="message-meta">
66.                                     <span class="author-name">@msg.Author</span>
67.                                     <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
68.                                 </div>
69.                                 <div class="message-content">@msg.Content</div>
70.                                 @if (msg.Reactions.Count > 0)
71.                                 {
72.                                     <div class="reactions-row">
73.                                         @foreach (var reaction in msg.Reactions)
74.                                         {
75.                                             <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
76.                                                     @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
77.                                                 @reaction.Emoji @reaction.Users.Count
78.                                             </button>
79.                                         }
80.                                     </div>
81.                                 }
82.                                 @if (threadSummaries.TryGetValue(msg.Id, out var summary))
83.                                 {
84.                                     <button class="thread-link" @onclick="() => OpenThread(msg.Id)">
85.                                         💬 @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
86.                                         <span class="thread-time">Last reply @FormatRelativeTime(summary.LastReplyAt)</span>
87.                                     </button>
88.                                 }
89.                             </div>
90.                             @if (emojiPickerMessageId == msg.Id)
91.                             {
92.                                 <div class="emoji-picker">
93.                                     @foreach (var emoji in commonEmojis)
94.                                     {
95.                                         <button class="emoji-btn" @onclick="() => PickEmoji(msg.Id, emoji)">@emoji</button>
96.                                     }
97.                                 </div>
98.                             }
99.                         </div>
100.                     }
101.                 }
102.             </div>
103. 
104.             <div class="message-input-area">
105.                 <textarea class="form-control" rows="2" placeholder="Message #@activeChannel.Name"
106.                           @bind="newMessage" @bind:event="oninput"
107.                           @onkeydown="HandleMainKeyDown"></textarea>
108.                 <button class="btn btn-primary send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessage)">
109.                     Send
110.                 </button>
111.             </div>
112.         }
113.         else if (isLoading)
114.         {
115.             <div class="d-flex justify-content-center align-items-center h-100">
116.                 <div class="spinner-border text-primary" role="status"></div>
117.             </div>
118.         }
119.     </div>
120. 
