131.                 @foreach (var msg in threadMessages)
132.                 {
133.                     var isRoot = msg.Id == openThreadRootId;
134.                     <div class="@(isRoot ? "thread-root-message" : "message-card")" @key="msg.Id">
135.                         <div class="avatar avatar-sm" style="background-color: @GetAvatarColor(msg.Author)">
136.                             @msg.Author[0]
137.                         </div>
138.                         <div class="message-body">
139.                             <div class="message-meta">
140.                                 <span class="author-name">@msg.Author</span>
141.                                 <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
142.                             </div>
143.                             <div class="message-content">@msg.Content</div>
144.                             @if (msg.Reactions.Count > 0)
145.                             {
146.                                 <div class="reactions-row">
147.                                     @foreach (var reaction in msg.Reactions)
148.                                     {
149.                                         <button class="reaction-pill @(reaction.Users.Contains("You") ? "reacted" : "")"
150.                                                 @onclick="() => ToggleReaction(msg.Id, reaction.Emoji)">
151.                                             @reaction.Emoji @reaction.Users.Count
152.                                         </button>
153.                                     }
154.                                 </div>
155.                             }
156.                         </div>
157.                     </div>
158.                 }
159.             </div>
160. 
161.             <div class="message-input-area">
